import unittest
from typing import Sequence
from pylint.graph import get_cycles


class TestGetCycles(unittest.TestCase):

    def test_empty_graph(self):
        """Test get_cycles with an empty graph dictionary."""
        result = get_cycles({})
        self.assertEqual(result, ())

    def test_single_vertex_no_edges(self):
        """Test get_cycles with a single vertex and no edges."""
        graph = {"A": set()}
        result = get_cycles(graph)
        self.assertEqual(result, [])

    def test_two_vertices_no_cycle(self):
        """Test get_cycles with two vertices and no cycle."""
        graph = {"A": {"B"}, "B": set()}
        result = get_cycles(graph)
        self.assertEqual(result, [])

    def test_simple_cycle(self):
        """Test get_cycles with a simple cycle A -> B -> A."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph)
        self.assertGreater(len(result), 0)
        # Check that we have at least one cycle involving A and B
        found_cycle = False
        for cycle in result:
            if "A" in cycle and "B" in cycle:
                found_cycle = True
        self.assertTrue(found_cycle)

    def test_self_loop(self):
        """Test get_cycles with a self-loop."""
        graph = {"A": {"A"}}
        result = get_cycles(graph)
        self.assertGreater(len(result), 0)
        # Check that we have at least one cycle with A
        found_cycle = False
        for cycle in result:
            if "A" in cycle:
                found_cycle = True
        self.assertTrue(found_cycle)

    def test_complex_graph_with_multiple_cycles(self):
        """Test get_cycles with a more complex graph containing multiple cycles."""
        graph = {
            "A": {"B", "C"},
            "B": {"D"},
            "C": {"D"},
            "D": {"A"}
        }
        result = get_cycles(graph)
        # Should detect cycles
        self.assertGreater(len(result), 0)

    def test_disconnected_components(self):
        """Test get_cycles with disconnected components."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"}
        }
        result = get_cycles(graph)
        # Should find cycles in both components
        self.assertGreaterEqual(len(result), 2)

    def test_linear_chain(self):
        """Test get_cycles with a linear chain (no cycles)."""
        graph = {"A": {"B"}, "B": {"C"}, "C": {"D"}, "D": set()}
        result = get_cycles(graph)
        self.assertEqual(result, [])

    def test_specified_vertices_subset(self):
        """Test get_cycles with a specified subset of vertices."""
        graph = {"A": {"B"}, "B": {"A"}, "C": {"D"}, "D": {"C"}}
        result = get_cycles(graph, ["A", "B"])
        # Should find cycles involving A and B
        self.assertGreaterEqual(len(result), 1)
        for cycle in result:
            for node in cycle:
                self.assertIn(node, ["A", "B"])

    def test_specified_vertices_none(self):
        """Test get_cycles with vertices parameter explicitly set to None."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph, None)
        self.assertGreaterEqual(len(result), 1)


if __name__ == "__main__":
    unittest.main()

items.class_constructor:
def __init__(
        self,
        graphname: str,
        rankdir: str | None = None,
        size: Any = None,
        ratio: Any = None,
        charset: str = "utf-8",
        renderer: str = "dot",
        additional_param: dict[str, Any] | None = None,
    ) -> None:
        if additional_param is None:
            additional_param = {}
        self.graphname = graphname
        self.renderer = renderer
        self.lines: list[str] = []
        self._source: str | None = None
        self.emit(f"digraph {normalize_node_id(graphname)} {{")
        if rankdir:
            self.emit(f"rankdir={rankdir}")
        if ratio:
            self.emit(f"ratio={ratio}")
        if size:
            self.emit(f'size="{size}"')
        if charset:
            assert charset.lower() in {
                "utf-8",
                "iso-8859-1",
                "latin1",
            }, f"unsupported charset {charset}"
            self.emit(f'charset="{charset}"')
        for param in additional_param.items():
            self.emit("=".join(param))
